#!/usr/bin/env node
// =============================================================================
// build-notebooklm-bundle — assemble a NON-SENSITIVE, redacted "spine" bundle of
// this project's doctrine + methodology + decisions for upload to an EXTERNAL
// comprehension lens (e.g. NotebookLM). (Darrell 2026-07-19.)
// =============================================================================
// SOVEREIGNTY GUARD (DATA-AS-EMPOWERMENT-NOT-EXTRACTION): NotebookLM is Google's
// cloud. Uploading is publishing off the NAS, so this bundle carries ONLY the
// design/doctrine SPINE — never the app's family data, real PII, seed-as-real, or
// secrets. It concatenates an explicit ALLOWLIST into a few combined Markdown files
// (NotebookLM caps source COUNT, not per-source size), and runs a REDACTION pass
// that scrubs internal IPs, Tailscale hostnames, emails, and token/secret-shaped
// strings before anything is written — with a transparent count of what was scrubbed.
//
// Run:  node scripts/build-notebooklm-bundle.mjs
// Out:  notebooklm-bundle/*.md  (git-ignored; regenerate any time the spine changes)
// =============================================================================

import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import { join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = join(ROOT, 'notebooklm-bundle');

// ── The ALLOWLIST — grouped into combined output sources ─────────────────────
const rootFoundations = join(ROOT, 'docs/00-foundations/_root');
const decisionsDir = join(ROOT, 'docs/decisions');
const mdIn = (dir) => (existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.md')).sort() : []);

const GROUPS = [
  { out: '01-layer0-identity.md', title: 'Layer 0 — Identity (CLAUDE.md)', files: [join(ROOT, 'CLAUDE.md')] },
  { out: '02-foundations.md', title: 'Layer 3 — Foundations (docs/00-foundations/_root)', files: mdIn(rootFoundations).map((f) => join(rootFoundations, f)) },
  { out: '03-decision-records.md', title: 'Decision Records (docs/decisions)', files: mdIn(decisionsDir).map((f) => join(decisionsDir, f)) },
  { out: '04-reviews.md', title: 'Reviews ledger (docs/reviews/REVIEWS.md)', files: [join(ROOT, 'docs/reviews/REVIEWS.md')] },
  { out: '05-icm-methodology.md', title: 'ICM methodology (one-page explainer)', files: [join(OUT_DIR, 'ICM-METHODOLOGY.md')] },
];

// ── The REDACTION pass — scrub anything sovereign before it leaves for Google ─
const REDACTIONS = [
  { name: 'internal-ip', re: /\b(?:192\.168|10|172\.(?:1[6-9]|2\d|3[01]))\.\d{1,3}\.\d{1,3}\b/g, to: '[REDACTED-INTERNAL-IP]' },
  { name: 'tailscale-host', re: /\b[\w-]+\.ts\.net\b/g, to: '[REDACTED-INTERNAL-HOST]' },
  { name: 'email', re: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g, to: '[REDACTED-EMAIL]' },
  { name: 'token-prefixed', re: /\b(?:sk|pk|ghp|gho|ghs|rk|xox[baprs])[-_][A-Za-z0-9]{16,}\b/g, to: '[REDACTED-TOKEN]' },
  { name: 'bearer', re: /Bearer\s+[A-Za-z0-9._-]{16,}/g, to: 'Bearer [REDACTED-TOKEN]' },
  { name: 'assigned-secret', re: /\b([A-Z][A-Z0-9_]*(?:TOKEN|SECRET|KEY|PASSWORD|PWD)[A-Z0-9_]*)\s*[:=]\s*['"]?[^\s'"#]{8,}/g, to: '$1=[REDACTED-SECRET]' },
];

function redact(text) {
  let out = text;
  const counts = {};
  for (const r of REDACTIONS) {
    let n = 0;
    out = out.replace(r.re, (...m) => { n += 1; return r.to.replace('$1', m[1] ?? ''); });
    if (n) counts[r.name] = n;
  }
  return { out, counts };
}

function mergeCounts(a, b) { for (const k of Object.keys(b)) a[k] = (a[k] || 0) + b[k]; return a; }

// ── Build ────────────────────────────────────────────────────────────────────
const totalRedactions = {};
const built = [];
let missing = 0;

for (const g of GROUPS) {
  const parts = [`# ${g.title}\n`];
  let included = 0;
  for (const f of g.files) {
    if (!existsSync(f)) { console.warn(`  ! missing (skipped): ${f.replace(ROOT + '/', '')}`); missing += 1; continue; }
    const raw = readFileSync(f, 'utf8');
    const { out, counts } = redact(raw);
    mergeCounts(totalRedactions, counts);
    parts.push(`\n\n---\n\n<!-- SOURCE: ${f.replace(ROOT + '/', '')} -->\n\n${out.trim()}\n`);
    included += 1;
  }
  const body = parts.join('');
  writeFileSync(join(OUT_DIR, g.out), body);
  const words = body.split(/\s+/).filter(Boolean).length;
  built.push({ out: g.out, title: g.title, included, words });
  console.log(`  wrote ${g.out}  (${included} file(s), ~${words.toLocaleString()} words)`);
}

// ── MANIFEST — what's inside, what was scrubbed, how to upload ────────────────
const stamp = process.argv[2] || 'run locally: date not injected';
const manifest = `# NotebookLM bundle — MANIFEST

Generated by \`scripts/build-notebooklm-bundle.mjs\`. ${stamp}

## What this is
The **non-sensitive doctrine + methodology + decision spine** of this project,
concatenated into ${built.length} combined Markdown files for upload to NotebookLM
(or any source-grounded reader). The repository remains the source of truth; this is
a lens over a copy.

## Sources in this bundle
${built.map((b) => `- **${b.out}** — ${b.title} · ${b.included} file(s) · ~${b.words.toLocaleString()} words`).join('\n')}

## Redaction report (scrubbed before write — nothing sovereign leaves)
${Object.keys(totalRedactions).length
    ? Object.entries(totalRedactions).map(([k, v]) => `- ${k}: ${v}`).join('\n')
    : '- (none matched)'}

Redaction is belt-and-suspenders on top of the allowlist: internal IPs, Tailscale
hostnames, emails, and token/secret-shaped strings are replaced with \`[REDACTED-…]\`.

## What is DELIBERATELY excluded (the sovereignty line)
- The app's family/financial data, real PII, and seed-as-real content
- \`.env\`, secrets, tokens, and any credential
- Anything under the running app's data path — this is DESIGN spine only

## How to upload
1. Open **notebooklm.google.com** → **New notebook**.
2. **Add source** → upload the \`.md\` files in this folder (drag them in).
3. Try: *Audio Overview* of the foundations; ask *"where do the decision records
   conflict or leave something unresolved?"*; generate a *briefing doc* of the ICM.

## Honest constraints (read before relying on it)
- It is **Google's cloud** — not sovereign. Treat everything here as published.
- It is a **snapshot** — re-run this script and re-upload when the spine changes.
- It **summarizes** — verify any answer against the repository, the source of truth.
`;
writeFileSync(join(OUT_DIR, 'MANIFEST.md'), manifest);
console.log(`  wrote MANIFEST.md`);

console.log(`\nBundle ready in notebooklm-bundle/ — ${built.length} sources, ` +
  `${Object.values(totalRedactions).reduce((a, b) => a + b, 0)} redactions` +
  (missing ? `, ${missing} missing file(s) skipped` : '') + '.');
